                return new BigDecimal("3.49");

            case CARTAO:
                if (parcelas <= 3) {
                    return BigDecimal.ZERO;
                } else {
                    BigDecimal taxa = new BigDecimal("0.0199");
                    BigDecimal juros = calcularJurosCarcao(totalPedido, taxa, parcelas);
                    return arredondar(juros);
                }

            default:
                return BigDecimal.ZERO;
        }
    }

    private BigDecimal calcularJurosCarcao(BigDecimal total, BigDecimal taxaMensal, int parcelas) {
        BigDecimal um = BigDecimal.ONE;
        BigDecimal taxaMais1 = um.add(taxaMensal);
        BigDecimal expoente = new BigDecimal(parcelas).negate();
        BigDecimal divisor = um.subtract(taxaMais1.pow(expoente.intValue(), new java.math.MathContext(20)));
        BigDecimal parcela = total.multiply(taxaMensal).divide(divisor, 20, RoundingMode.HALF_EVEN);
        parcela = arredondar(parcela);

        BigDecimal totalComJuros = parcela.multiply(new BigDecimal(parcelas));
        return subtrair(totalComJuros, total);
    }

    private BigDecimal calcularValorParcela(CheckoutRequest request, BigDecimal totalFinal, int parcelas) {
        if (request.getFormaPagamento() == FormaPagamento.CARTAO && parcelas > 3) {
            BigDecimal taxa = new BigDecimal("0.0199");
            BigDecimal um = BigDecimal.ONE;
            BigDecimal taxaMais1 = um.add(taxa);
            BigDecimal expoente = new BigDecimal(parcelas).negate();
            BigDecimal divisor = um.subtract(taxaMais1.pow(expoente.intValue(), new java.math.MathContext(20)));
            BigDecimal valor = totalFinal.multiply(taxa).divide(divisor, 20, RoundingMode.HALF_EVEN);
            return arredondar(valor);
        } else {
            return arredondar(totalFinal.divide(new BigDecimal(parcelas), 20, RoundingMode.HALF_EVEN));
        }
    }

    private BigDecimal calcularCreditoClube(CheckoutRequest request, BigDecimal subtotalProdutos) {
        switch (request.getNivelClube()) {
            case BRONZE:
                return BigDecimal.ZERO;
            case PRATA:
                return arredondar(subtotalProdutos.multiply(new BigDecimal("0.02")));
            case OURO:
                return arredondar(subtotalProdutos.multiply(new BigDecimal("0.05")));
            default:
                return BigDecimal.ZERO;
        }
    }

    private BigDecimal calcularPesoTotal(CheckoutRequest request) {
        BigDecimal pesoTotal = BigDecimal.ZERO;
        for (ItemCarrinho item : request.getItens()) {
            BigDecimal peso = item.getPesoKg().multiply(new BigDecimal(item.getQuantidade()));
            pesoTotal = pesoTotal.add(peso);
        }
        return pesoTotal;
    }

    private BigDecimal arredondar(BigDecimal valor) {
        if (valor == null) {
            return BigDecimal.ZERO;
        }
        return valor.setScale(2, ROUNDING);
    }

    private BigDecimal somar(BigDecimal... valores) {
        BigDecimal resultado = BigDecimal.ZERO;
        for (BigDecimal valor : valores) {
            resultado = resultado.add(valor);
        }
        return resultado;
    }

    private BigDecimal subtrair(BigDecimal minuendo, BigDecimal subtraendo) {
        return minuendo.subtract(subtraendo);
    }
}

